import type { Href } from "expo-router";

// Workspace routes (plan 05 §W1). Cast: the typed-routes manifest is
// regenerated by `expo start`, not by tsc (same as `sourceHref`).

/** «مساحة العمل» of a conversation. */
export function workspaceHref(conversationId: string): Href {
  return `/workspace/${encodeURIComponent(conversationId)}` as Href;
}

/** One workspace item (any kind). */
export function workspaceItemHref(itemId: string): Href {
  return `/workspace/item/${encodeURIComponent(itemId)}` as Href;
}
